using System;
using EmberBastion;
class SupportStunChecks {
 static void Near(double value,double expected,string name){if(Math.Abs(value-expected)>1e-8)throw new Exception(name+": "+value+" != "+expected);}
 static void Main(){try{var b=new Battle();b.Gold=1000;if(!b.Place(1,0)||!b.Place(4,1))throw new Exception("setup");var attacker=b.At(0);var smith=b.At(1);double haste,bonus;b.SupportBonuses(attacker,out haste,out bonus);Near(haste,.25,"normal support");smith.Stun=1;b.SupportBonuses(attacker,out haste,out bonus);Near(haste,0,"stunned support stops");var restored=Battle.RestorePreparation(b.SavePreparation());restored.SupportBonuses(restored.At(0),out haste,out bonus);Near(haste,0,"stun preserved on restore");restored.At(1).Stun=0;restored.SupportBonuses(restored.At(0),out haste,out bonus);Near(haste,.25,"recovery restores support");if(!b.Place(4,10))throw new Exception("second support");b.SupportBonuses(attacker,out haste,out bonus);Near(haste,.25,"second active supporter remains effective");var live=new Battle();live.Gold=1000;live.Place(1,0);live.Place(4,1);if(!live.Start())throw new Exception("start");live.Enemies.Add(new Enemy{Id=900,Kind=3,HP=.01,MaxHP=1,Burn=1,Position=live.Field.Slots[1]});live.Step(1.0/60);if(live.At(1).Stun<=0)throw new Exception("bomb death did not stun technician");live.SupportBonuses(live.At(0),out haste,out bonus);Near(haste,0,"bomb stun disables support");for(int i=0;i<100;i++)live.Step(1.0/60);live.SupportBonuses(live.At(0),out haste,out bonus);Near(haste,.25,"support recovers after stun duration");Console.WriteLine("PASS technician stun, saved state, recovery, bomb death and second supporter");}catch(Exception e){Console.Error.WriteLine(e);Environment.Exit(1);}}
}

